import chess
import numpy as np
import pandas as pd

N_COLS = 769

def main():
    #below code generated by claude to test my translate_fen function
    fen = "4k3/8/8/3p4/8/5N2/8/4K3 w - -"
    x = translate_fen(fen) 

    expected = np.zeros(769, dtype=x.dtype)
    expected[85]  = 1   
    expected[324] = 1   
    expected[419] = 1   
    expected[764] = 1   
    expected[768] = 1   

    assert x.shape == (769,), f"wrong shape: {x.shape}"
    assert x.sum() == 5, f"expected 5 ones, got {x.sum()}"
    assert np.array_equal(x, expected), f"mismatch at columns {np.nonzero(x != expected)[0]}"
    print("translate_fen test passed")

def translate_fen(fen):
    board = chess.Board(fen)
    x = np.zeros(N_COLS, dtype=np.uint8)
    for square, piece in board.piece_map().items():
        piece_index = piece.piece_type - 1
        if piece.color == chess.BLACK: piece_index += 6

        x[piece_index * 64 + square] = 1
    if board.turn == chess.WHITE: x[768] = 1
        
    return x


if __name__ == "__main__":
    main()